import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Users, 
  ShoppingBag, 
  CreditCard, 
  BarChart3, 
  MessageSquare, 
  Settings, 
  LogOut, 
  User, 
  Shield,
  TrendingUp,
  Bell,
  FileText,
  Calendar,
  ShieldCheck,
  Database,
  Server
} from 'lucide-react';

const Sidebar = ({ sidebarOpen, location: propLocation, onLogout }) => {
  const userEmail = localStorage.getItem('userEmail') || 'enzo@gmail.com';
  // useLocation hook as primary source when `location` prop isn't provided.
  // If component is ever rendered outside a Router, fallback to window.location (if available).
  let loc;
  try {
    const hookLocation = useLocation();
    loc = propLocation ?? hookLocation ?? (typeof window !== 'undefined' ? window.location : { pathname: '/' });
  } catch (e) {
    // If useLocation throws (component rendered outside Router), fallback to prop or window
    loc = propLocation ?? (typeof window !== 'undefined' ? window.location : { pathname: '/' });
  }

  const navItems = [
    { 
      to: "/dashboard", 
      icon: <LayoutDashboard className="h-5 w-5" />, 
      label: "Tableau de bord", 
      exact: true 
    },
    { 
      to: "/dashboard/users", 
      icon: <Users className="h-5 w-5" />, 
      label: "Utilisateurs", 
      badge: "42", 
      badgeColor: "accent" 
    },
    { 
      to: "/dashboard/products", 
      icon: <ShoppingBag className="h-5 w-5" />, 
      label: "Produits", 
      badge: "156", 
      badgeColor: "secondary" 
    },
    { 
      to: "/dashboard/orders", 
      icon: <CreditCard className="h-5 w-5" />, 
      label: "Commandes", 
      badge: "24", 
      badgeColor: "primary" 
    },
    { 
      to: "/dashboard/analytics", 
      icon: <BarChart3 className="h-5 w-5" />, 
      label: "Analytique" 
    },
    { 
      to: "/dashboard/messages", 
      icon: <MessageSquare className="h-5 w-5" />, 
      label: "Messages", 
      badge: "3", 
      badgeColor: "accent" 
    },
    { 
      to: "/dashboard/settings", 
      icon: <Settings className="h-5 w-5" />, 
      label: "Paramètres" 
    },
  ];

  const quickStats = [
    { label: "Utilisateurs actifs", value: "1,234" },
    { label: "Taux de conversion", value: "3.42%", valueColor: "text-accent-500" },
    { label: "Commande moyenne", value: "$245", valueColor: "text-primary-500" },
    { label: "Satisfaction", value: "4.8/5", valueColor: "text-green-500" },
  ];

  const secondaryNav = [
    { to: "/dashboard/reports", icon: <FileText className="h-4 w-4" />, label: "Rapports" },
    { to: "/dashboard/calendar", icon: <Calendar className="h-4 w-4" />, label: "Calendrier" },
    { to: "/dashboard/notifications", icon: <Bell className="h-4 w-4" />, label: "Notifications" },
  ];

  const systemNav = [
    { to: "/dashboard/system", icon: <Server className="h-4 w-4" />, label: "Système" },
    { to: "/dashboard/database", icon: <Database className="h-4 w-4" />, label: "Base de données" },
    { to: "/dashboard/backup", icon: <ShieldCheck className="h-4 w-4" />, label: "Sauvegarde" },
  ];

  return (
    <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-r border-neutral-200/50 dark:border-neutral-800/50 transform transition-transform duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
      <div className="flex flex-col h-full">
        {/* Logo */}
        <div className="p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
          <div className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <Shield className="h-6 w-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-neutral-900 dark:text-white">Admin<span className="text-primary-600 dark:text-primary-400">Pro</span></h1>
              <p className="text-xs text-neutral-500 dark:text-neutral-400">Dashboard Premium</p>
            </div>
          </div>
        </div>

        {/* User Profile */}
        <div className="p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
          <div className="flex items-center space-x-3">
            <div className="h-12 w-12 rounded-xl bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
              <User className="h-6 w-6 text-white" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-neutral-900 dark:text-white truncate">
                Enzo Admin
              </p>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 truncate">
                {userEmail}
              </p>
              <div className="flex items-center mt-1">
                <div className="h-2 w-2 rounded-full bg-green-500 mr-2"></div>
                <span className="text-xs text-green-600 dark:text-green-400">En ligne</span>
              </div>
            </div>
          </div>
        </div>

        {/* Navigation principale */}
        <nav className="flex-1 p-4 overflow-y-auto">
          <div className="mb-6">
            <h3 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-3 px-3">
              Navigation
            </h3>
            <ul className="space-y-1">
              {navItems.map((item) => {
                const isActive = item.exact 
                  ? loc.pathname === item.to
                  : loc.pathname.startsWith(item.to);

                return (
                  <li key={item.to}>
                    <Link 
                      to={item.to} 
                      className={`flex items-center space-x-3 px-4 py-3 rounded-xl ${isActive ? 'bg-gradient-to-r from-primary-500 to-primary-600 text-white font-medium' : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors'}`}
                    >
                      {item.icon}
                      <span>{item.label}</span>
                      {item.badge && (
                        <span className={`ml-auto px-2 py-1 text-xs font-medium bg-${item.badgeColor}-500 text-white rounded-full`}>
                          {item.badge}
                        </span>
                      )}
                    </Link>
                  </li>
                );
              })}
            </ul>
          </div>

          {/* Navigation secondaire */}
          <div className="mb-6">
            <h3 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-3 px-3">
              Outils
            </h3>
            <ul className="space-y-1">
              {secondaryNav.map((item) => (
                <li key={item.to}>
                  <Link 
                    to={item.to} 
                    className={`flex items-center space-x-3 px-4 py-2.5 rounded-xl text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors ${loc.pathname === item.to ? 'bg-neutral-100 dark:bg-neutral-800/50 text-primary-600 dark:text-primary-400' : ''}`}
                  >
                    {item.icon}
                    <span className="text-sm">{item.label}</span>
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Système */}
          <div className="mb-6">
            <h3 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider mb-3 px-3">
              Système
            </h3>
            <ul className="space-y-1">
              {systemNav.map((item) => (
                <li key={item.to}>
                  <Link 
                    to={item.to} 
                    className={`flex items-center space-x-3 px-4 py-2.5 rounded-xl text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors ${loc.pathname === item.to ? 'bg-neutral-100 dark:bg-neutral-800/50 text-primary-600 dark:text-primary-400' : ''}`}
                  >
                    {item.icon}
                    <span className="text-sm">{item.label}</span>
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Quick Stats */}
          <div className="mb-6 p-4 rounded-xl bg-gradient-to-r from-neutral-50 to-white dark:from-neutral-800 dark:to-neutral-900 border border-neutral-200/50 dark:border-neutral-700/50">
            <h3 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-4 flex items-center">
              <TrendingUp className="h-4 w-4 mr-2" />
              Statistiques rapides
            </h3>
            <div className="space-y-3">
              {quickStats.map((stat, index) => (
                <div key={index} className="flex items-center justify-between">
                  <span className="text-xs text-neutral-500 dark:text-neutral-400">{stat.label}</span>
                  <span className={`text-sm font-medium ${stat.valueColor || 'text-neutral-900 dark:text-white'}`}>
                    {stat.value}
                  </span>
                </div>
              ))}
            </div>
            <div className="mt-4 pt-4 border-t border-neutral-200/50 dark:border-neutral-700/50">
              <div className="flex items-center justify-between">
                <span className="text-xs text-neutral-500 dark:text-neutral-400">Performance</span>
                <div className="flex items-center">
                  <div className="h-2 w-16 bg-neutral-200 dark:bg-neutral-700 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-gradient-to-r from-green-500 to-accent-500"
                      style={{ width: '85%' }}
                    ></div>
                  </div>
                  <span className="text-xs font-medium text-green-600 dark:text-green-400 ml-2">85%</span>
                </div>
              </div>
            </div>
          </div>

          {/* App Status */}
          <div className="p-4 rounded-xl bg-gradient-to-r from-primary-50 to-primary-100/50 dark:from-primary-900/20 dark:to-primary-800/10 border border-primary-200/50 dark:border-primary-800/30">
            <h3 className="text-sm font-medium text-primary-700 dark:text-primary-300 mb-3">
              État du système
            </h3>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <div className="h-2 w-2 rounded-full bg-green-500 mr-2"></div>
                  <span className="text-xs text-neutral-600 dark:text-neutral-400">Serveur</span>
                </div>
                <span className="text-xs font-medium text-green-600 dark:text-green-400">En ligne</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <div className="h-2 w-2 rounded-full bg-green-500 mr-2"></div>
                  <span className="text-xs text-neutral-600 dark:text-neutral-400">Base de données</span>
                </div>
                <span className="text-xs font-medium text-green-600 dark:text-green-400">Active</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <div className="h-2 w-2 rounded-full bg-yellow-500 mr-2"></div>
                  <span className="text-xs text-neutral-600 dark:text-neutral-400">Cache</span>
                </div>
                <span className="text-xs font-medium text-yellow-600 dark:text-yellow-400">79%</span>
              </div>
            </div>
          </div>
        </nav>

        {/* Footer */}
        <div className="p-4 border-t border-neutral-200/50 dark:border-neutral-800/50">
          {/* Logout Button */}
          <button
            onClick={onLogout}
            className="flex items-center justify-center space-x-2 w-full px-4 py-3 rounded-xl border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors mb-3"
          >
            <LogOut className="h-5 w-5" />
            <span className="font-medium">Déconnexion</span>
          </button>

          {/* Version Info */}
          <div className="flex items-center justify-between text-xs text-neutral-500 dark:text-neutral-500">
            <span>Version 2.1.0</span>
            <span>© 2024 AdminPro</span>
          </div>
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;
